<script lang="ts">
 import {onMount} from 'svelte';
 import {initialState,step,sampleStory,validateStory,type Story,type Cue,type CueKind,type State} from '$lib/courtroom/story/engine';
 import {saveStory,loadStory} from '$lib/courtroom/story/store';
 let story:Story=$state(structuredClone(sampleStory));
 let sim:State=$state(initialState(sampleStory));
 let selected=$state<string|null>(null);
 let playing=$state(false);
 let elapsed=$state(0);
 let message=$state('');
 let importedFile:HTMLInputElement;
 const kinds:CueKind[]=['dialogue','animation','emotion','evidence','phase'];
 let ordered=$derived([...story.cues].sort((a,b)=>a.tick-b.tick));
 let cue=$derived(story.cues.find(c=>c.id===selected));
 const maxTicks=600;
 function patchCue(id:string, patch:Partial<Cue>){story={...story,cues:story.cues.map(c=>c.id===id?{...c,...patch}:c)};}
 function addCue(){const id=`cue-${Date.now().toString(36)}`;story={...story,cues:[...story.cues,{id,tick:sim.tick+30,actorId:story.actors[0]?.id??'alice',kind:'dialogue',value:'New event'}]};selected=id;}
 function removeCue(){story={...story,cues:story.cues.filter(c=>c.id!==selected)};selected=null;}
 function seek(tick:number){let next=initialState(story);for(let t=0;t<Math.min(tick,108000);t+=300)next=step(story,next,{type:'TICK',steps:Math.min(300,tick-t)});sim=next;elapsed=tick/30;}
 function download(){const blob=new Blob([JSON.stringify(story,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`${story.id}.story.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function persistStory(){try{await saveStory($state.snapshot(story));message='Saved in IndexedDB';}catch{message='Could not save story locally';}}
 async function restoreStory(){try{const saved=await loadStory(story.id);if(saved){story=saved;seek(0);message='Loaded';}else message='No saved story';}catch{message='Could not load story locally';}}
 async function upload(event:Event){const f=(event.currentTarget as HTMLInputElement).files?.[0];if(!f)return;try{const v:unknown=JSON.parse(await f.text());if(!validateStory(v))throw new Error('Invalid story schema');story=v;seek(0);message='Story imported';}catch(e){message=e instanceof Error?e.message:String(e);}}
 onMount(()=>{let frame=0,last=performance.now(),acc=0;function loop(now:number){const dt=Math.min(0.25,(now-last)/1000);last=now;if(playing){acc+=dt;while(acc>=1/30){sim=step(story,sim,{type:'TICK'});acc-=1/30;}elapsed=sim.tick/30;}frame=requestAnimationFrame(loop);}frame=requestAnimationFrame(loop);return()=>cancelAnimationFrame(frame);});
</script>
<svelte:head><title>Courtroom Timeline Studio</title></svelte:head>
<main>
 <header><div><h1>Courtroom Timeline Studio</h1><p>Deterministic cues, actor behavior, and fictional story progression • 30 ticks/sec</p></div><nav><button onclick={addCue}>+ Cue</button><button onclick={()=>{playing=!playing}}>{playing?'Pause':'Play'}</button><button onclick={()=>{playing=false;seek(0)}}>Reset</button><button onclick={download}>Export JSON</button><button onclick={()=>importedFile?.click()}>Import</button><input aria-label="Import story" type="file" accept="application/json" bind:this={importedFile} onchange={upload} hidden /></nav></header>
 <div class="meta"><label>Story title <input bind:value={story.title}/></label><label>Story ID <input bind:value={story.id}/></label><button onclick={persistStory}>Save locally</button><button onclick={restoreStory}>Load locally</button><span role="status">{message}</span></div>
 <section class="sim"><div><strong>Simulation</strong><p>Phase: {sim.phase} · Tick {sim.tick} · {elapsed.toFixed(2)} sec · Evidence: {sim.evidence.join(', ')||'none'}</p></div><label>Scrub <input aria-label="Timeline scrubber" type="range" min="0" max={maxTicks} value={Math.min(maxTicks,sim.tick)} oninput={(e)=>{playing=false;seek(Number((e.currentTarget as HTMLInputElement).value));}}/></label><div class="dialogue">{sim.transcript.at(-1)?.text??'Press play to begin the fictional case.'}</div><div class="moods">{#each story.actors as actor}<span>{actor.name}: {sim.mood[actor.id]??'neutral'} / {sim.animations[actor.id]??'idle'}</span>{/each}</div></section>
 <section class="timeline"><div class="scale"><span>0s</span><span>5s</span><span>10s</span><span>15s</span><span>20s</span></div>{#each kinds as kind}<div class="track"><strong>{kind}</strong><div class="lane">{#each ordered.filter(c=>c.kind===kind) as c(c.id)}<button class:selected={selected===c.id} title={`${c.tick/30}s · ${c.value}`} style:left={`${Math.min(99,c.tick/maxTicks*100)}%`} onclick={()=>selected=c.id}>{c.value.slice(0,16)}</button>{/each}</div></div>{/each}</section>
 <section class="details"><div><h2>Event Inspector</h2>{#if cue}<label>Time (tick)<input type="number" min="0" max="108000" value={cue.tick} onchange={e=>patchCue(cue.id,{tick:Math.max(0,Math.floor(Number((e.currentTarget as HTMLInputElement).value)))})}/></label><label>Actor<select value={cue.actorId} onchange={e=>patchCue(cue.id,{actorId:(e.currentTarget as HTMLSelectElement).value})}>{#each story.actors as actor}<option value={actor.id}>{actor.name}</option>{/each}</select></label><label>Kind<select value={cue.kind} onchange={e=>patchCue(cue.id,{kind:(e.currentTarget as HTMLSelectElement).value as CueKind})}>{#each kinds as k}<option value={k}>{k}</option>{/each}</select></label><label>Value<textarea value={cue.value} oninput={e=>patchCue(cue.id,{value:(e.currentTarget as HTMLTextAreaElement).value})}></textarea></label><label>Required evidence<input value={cue.requiredEvidence??''} onchange={e=>patchCue(cue.id,{requiredEvidence:(e.currentTarget as HTMLInputElement).value||undefined})}/></label><button onclick={removeCue}>Delete event</button>{:else}<p>Select a cue to edit it.</p>{/if}</div><div><h2>Ordered events</h2><ol>{#each ordered as c(c.id)}<li><button onclick={()=>selected=c.id}><b>{(c.tick/30).toFixed(1)}s</b> {c.kind} — {c.actorId}: {c.value}</button></li>{/each}</ol></div></section>
</main>
<style>
 main{background:#0d1420;color:#e5edf6;font-family:system-ui,sans-serif;max-width:1380px;margin:auto;padding:24px}header{display:flex;justify-content:space-between;gap:18px;flex-wrap:wrap;align-items:center}h1{margin:0;font-size:1.7rem}p{color:#9caec3;font-size:.9rem}nav,.meta{display:flex;gap:8px;flex-wrap:wrap;align-items:center}button{background:#26374b;color:#f1f6fb;border:1px solid #46617c;padding:8px 12px;border-radius:6px;cursor:pointer}button:hover,.selected{background:#466aa1!important}.meta,.sim,.timeline,.details{background:#152233;border:1px solid #2b4057;border-radius:12px;padding:16px;margin-top:16px}input,select,textarea{background:#091624;color:white;border:1px solid #506881;border-radius:5px;padding:7px}label{display:flex;flex-direction:column;gap:5px;font-size:.85rem}.meta label{min-width:190px}.sim{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sim .dialogue{background:#0b1828;border:1px solid #425b78;padding:18px;border-radius:8px;min-height:52px}.moods{display:flex;gap:15px;flex-wrap:wrap}.scale{display:flex;justify-content:space-between;margin-left:110px;color:#97a9c0;font-size:.8rem}.track{display:flex;align-items:center;min-height:55px;border-bottom:1px solid #293e53}.track>strong{width:110px;text-transform:capitalize}.lane{position:relative;flex:1;height:45px;background:repeating-linear-gradient(90deg,#142238 0,#142238 calc(25% - 1px),#31445c 25%);border-radius:5px}.lane button{position:absolute;top:6px;transform:translateX(-10%);max-width:140px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:.7rem}.details{display:grid;grid-template-columns:minmax(270px,1fr) minmax(270px,1fr);gap:30px}.details label{margin-bottom:12px}.details textarea{min-height:60px}.details ol{max-height:380px;overflow:auto;padding-left:23px}.details li{margin:5px 0}.details li button{text-align:left;width:100%}@media(max-width:760px){.sim,.details{grid-template-columns:1fr}.lane button{max-width:80px}}
</style>
